def fusion_cost(weights):
    n = len(weights)
    if n < 2:
        return 0
    totals = [0]
    costs = []
    for i in range(n):
        totals.append(totals[-1] + weights[i])
        row = []
        for j in range(n):
            row.append(0)
        costs.append(row)
    for width in range(2, n + 1):
        for left in range(n - width + 1):
            right = left + width - 1
            best = -1
            for split in range(left, right):
                cost = costs[left][split] + costs[split + 1][right]
                if best == -1 or cost < best:
                    best = cost
            costs[left][right] = best + totals[right + 1] - totals[left]
    return costs[0][n - 1]

